// Generated by secure-by-design v0.1.0 for AI accountability (ISO 27001 A.8.15 +
// alignment with ISO/IEC 42001 §8.4 and EU AI Act Art. 12-style logging).
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/ai-decision-log.md
//
// Every AI inference flows through this wrapper. It records:
//   - which AI system (matches aiSystems[].name in manifest)
//   - the input categories (without raw PHI/PII — only category names)
//   - the output (or its hash if too large / sensitive)
//   - latency, model id, prompt+response token counts
//   - whether human oversight gate was invoked (and outcome)
//
// You can replay this log to: audit, debug, monitor for drift, support
// data-principal access (DPDP §11) for AI-mediated decisions.

import { createHash } from 'node:crypto';
import { auditLog } from '../security/audit_log';
import { phiRedact } from '../security/phi_redaction';

export interface DecisionContext {
  systemName: string;        // matches manifest.aiSystems[].name
  actor: string;             // who triggered (physician ID, service ID)
  dataPrincipalId?: string;  // patient / data principal whose data is processed
  inputCategoryNames: string[]; // categories from manifest (not raw data!)
  modelId?: string;          // populated by the wrapped call when available
  metadata?: Record<string, unknown>;
}

export interface DecisionRecord extends DecisionContext {
  timestamp: string;
  latencyMs: number;
  outcome: 'success' | 'failure' | 'oversight-blocked';
  outputHash?: string;       // SHA-256 of stringified output
  outputPreview?: string;    // first 200 chars, PHI-redacted
  error?: string;
  tokensIn?: number;
  tokensOut?: number;
  oversightRequired?: boolean;
  oversightProvidedBy?: string;
}

export interface DecisionSink {
  write(record: DecisionRecord): Promise<void>;
}

class StderrDecisionSink implements DecisionSink {
  async write(record: DecisionRecord): Promise<void> {
    // eslint-disable-next-line no-console
    console.error(JSON.stringify({ kind: 'ai-decision', ...record }));
  }
}

let sink: DecisionSink = new StderrDecisionSink();
export function setDecisionSink(s: DecisionSink): void { sink = s; }

function hashOf(value: unknown): string {
  const s = typeof value === 'string' ? value : JSON.stringify(value);
  return createHash('sha256').update(s).digest('hex');
}

function previewOf(value: unknown): string {
  const s = typeof value === 'string' ? value : JSON.stringify(value);
  return phiRedact(s.slice(0, 200));
}

/**
 * Wrap an AI inference call. Every AI invocation in your product should be wrapped.
 *
 *   const result = await decisionLog(
 *     { systemName: 'clinical-suggestion-engine', actor: physicianId,
 *       dataPrincipalId: patientId, inputCategoryNames: ['patient-clinical'] },
 *     () => openai.chat.completions.create({ model: 'gpt-4o', messages: [...] }),
 *   );
 *
 * The result is returned as-is; the side effect is the decision log record.
 */
export async function decisionLog<T>(
  ctx: DecisionContext,
  fn: () => Promise<T>,
): Promise<T> {
  const startedAt = Date.now();
  try {
    const result = await fn();
    const record: DecisionRecord = {
      ...ctx,
      timestamp: new Date(startedAt).toISOString(),
      latencyMs: Date.now() - startedAt,
      outcome: 'success',
      outputHash: hashOf(result),
      outputPreview: previewOf(result),
    };
    await sink.write(record);
    await auditLog.event(`ai.${ctx.systemName}.inference`, {
      actor: ctx.actor,
      target: ctx.dataPrincipalId,
      attrs: { latencyMs: record.latencyMs, outputHash: record.outputHash },
    });
    return result;
  } catch (e) {
    const record: DecisionRecord = {
      ...ctx,
      timestamp: new Date(startedAt).toISOString(),
      latencyMs: Date.now() - startedAt,
      outcome: 'failure',
      error: e instanceof Error ? e.message : 'unknown',
    };
    await sink.write(record);
    await auditLog.event(`ai.${ctx.systemName}.inference`, {
      actor: ctx.actor,
      target: ctx.dataPrincipalId,
      severity: 'ERROR',
      outcome: 'failure',
      attrs: { latencyMs: record.latencyMs, error: record.error },
    });
    throw e;
  }
}
